import rawBangs from "./bangs.json";

// Generated by scripts/generate-bangs.ts — trigger -> url template, or
// [template, landing domain] when the two have different origins.
const bangs = rawBangs as unknown as Record<string, string | [string, string] | undefined>;

const query = new URLSearchParams(location.search).get("q")?.trim() ?? "";

if (query) {
  redirect(query);
} else {
  // Homepage UI (and its CSS) is only fetched when there's nothing to redirect.
  void import("./page");
}

function getBang(trigger: string) {
  return Object.prototype.hasOwnProperty.call(bangs, trigger) ? bangs[trigger] : undefined;
}

function redirect(fullQuery: string) {
  const match = /!(\S+)/.exec(fullQuery);
  const candidate = match?.[1]?.toLowerCase();
  const entry =
    (candidate ? getBang(candidate) : undefined) ??
    getBang(localStorage.getItem("default-bang") ?? "g") ??
    getBang("g");
  if (!entry) return;

  const [urlTemplate, domain] = typeof entry === "string" ? [entry, undefined] : entry;

  // Remove the first bang from the query
  const cleanQuery = fullQuery.replace(/!\S+\s*/, "").trim();

  // If the query is just `!gh`, go to `github.com` instead of `github.com/search?q=`
  if (cleanQuery === "") {
    // String entries are guaranteed parseable: the generator stores a
    // [template, domain] pair whenever the template's origin differs from `d`.
    location.replace(domain ? `https://${domain}` : new URL(urlTemplate).origin);
    return;
  }

  location.replace(
    urlTemplate.replace(
      "{{{s}}}",
      // Replace %2F with / to fix formats like "!ghr t3dotgg/unduck"
      encodeURIComponent(cleanQuery).replace(/%2F/g, "/"),
    ),
  );
}
